CREATE TYPE public.app_role AS ENUM ('admin', 'user');
CREATE TABLE public.user_roles (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE, role public.app_role NOT NULL, UNIQUE(user_id, role));
GRANT SELECT ON public.user_roles TO authenticated;
GRANT ALL ON public.user_roles TO service_role;
ALTER TABLE public.user_roles ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Read own roles" ON public.user_roles FOR SELECT TO authenticated USING (user_id = auth.uid());
CREATE FUNCTION public.has_role(_user_id uuid, _role public.app_role) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path = public AS $$ SELECT EXISTS (SELECT 1 FROM public.user_roles WHERE user_id = _user_id AND role = _role) $$;
CREATE TABLE public.player_access (user_id uuid PRIMARY KEY REFERENCES public.profiles(id) ON DELETE CASCADE, banned boolean NOT NULL DEFAULT false, kicked_at timestamptz);
GRANT SELECT ON public.player_access TO authenticated;
GRANT ALL ON public.player_access TO service_role;
ALTER TABLE public.player_access ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Read own access" ON public.player_access FOR SELECT TO authenticated USING (user_id = auth.uid());
CREATE FUNCTION public.player_is_active() RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path = public AS $$ SELECT auth.uid() IS NOT NULL AND NOT EXISTS (SELECT 1 FROM public.player_access WHERE user_id = auth.uid() AND (banned OR (kicked_at IS NOT NULL AND coalesce((auth.jwt()->>'iat')::bigint,0) <= floor(extract(epoch FROM kicked_at))))) $$;
CREATE POLICY "Require active player" ON public.profiles AS RESTRICTIVE FOR ALL TO authenticated USING (public.player_is_active()) WITH CHECK (public.player_is_active());
CREATE FUNCTION public.game_access() RETURNS jsonb LANGUAGE sql STABLE SECURITY DEFINER SET search_path = public AS $$ SELECT jsonb_build_object('active', public.player_is_active(), 'banned', coalesce((SELECT banned FROM public.player_access WHERE user_id = auth.uid()), false), 'admin', public.has_role(auth.uid(), 'admin')) $$;
CREATE FUNCTION public.coins_leaderboard() RETURNS TABLE(username text, coins integer) LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path = public AS $$ BEGIN IF NOT public.player_is_active() THEN RAISE EXCEPTION 'Sign in to view players'; END IF; RETURN QUERY SELECT p.username, p.coins FROM public.profiles p ORDER BY p.coins DESC, p.username ASC; END $$;
CREATE FUNCTION public.admin_players() RETURNS TABLE(id uuid, username text, coins integer, banned boolean) LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path = public AS $$ BEGIN IF NOT public.player_is_active() OR NOT public.has_role(auth.uid(), 'admin') THEN RAISE EXCEPTION 'Admin access required'; END IF; RETURN QUERY SELECT p.id, p.username, p.coins, coalesce(a.banned, false) FROM public.profiles p LEFT JOIN public.player_access a ON a.user_id = p.id ORDER BY p.username; END $$;
CREATE FUNCTION public.moderate_player(target uuid, action text) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$ BEGIN IF NOT public.player_is_active() OR NOT public.has_role(auth.uid(), 'admin') THEN RAISE EXCEPTION 'Admin access required'; END IF; IF action NOT IN ('kick','ban','unban') THEN RAISE EXCEPTION 'Invalid action'; END IF; IF public.has_role(target, 'admin') THEN RAISE EXCEPTION 'Admin accounts cannot be moderated'; END IF; IF NOT EXISTS (SELECT 1 FROM public.profiles WHERE id = target) THEN RAISE EXCEPTION 'Player not found'; END IF; INSERT INTO public.player_access(user_id) VALUES (target) ON CONFLICT DO NOTHING; IF action = 'kick' THEN UPDATE public.player_access SET kicked_at = clock_timestamp() WHERE user_id = target; ELSIF action = 'ban' THEN UPDATE public.player_access SET banned = true WHERE user_id = target; ELSE UPDATE public.player_access SET banned = false WHERE user_id = target; END IF; END $$;
REVOKE ALL ON FUNCTION public.has_role(uuid, public.app_role), public.player_is_active(), public.game_access(), public.coins_leaderboard(), public.admin_players(), public.moderate_player(uuid,text) FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.has_role(uuid, public.app_role), public.player_is_active(), public.game_access(), public.coins_leaderboard(), public.admin_players(), public.moderate_player(uuid,text) TO authenticated, service_role;